def norm_sg07(rows):
    def clean_row(row):
        row = row.strip()
        row = '-'.join(row.split('  ', maxsplit=1))
        return row

    cleaned_rows = [clean_row(row) for row in rows]
    unique_rows = []
    prev_cleaned_row = None
    for row in cleaned_rows:
        row_lower = row.lower()
        if prev_cleaned_row is None or row_lower != prev_cleaned_row.lower():
            unique_rows.append(row)
            prev_cleaned_row = row

    def sort_key(row):
        return (-len(row), row)

    sorted_rows = sorted(unique_rows, key=sort_key)
    limited_rows = [row[:8] for row in sorted_rows]
    return limited_rows
