def norm_sg09(rows):
    import re

    def replace_long_spaces(line):
        return re.sub(r'\s{3,}', '-', line)

    def trim_edges(line):
        return line.strip()

    def remove_adjacent_duplicates(lines):
        seen = set()
        result = []
        for line in lines:
            if line not in seen:
                seen.add(line)
                result.append(line)
        return result

    def sort_desc(lines):
        return sorted(lines, reverse=True)

    def keep_last_9_chars(line):
        return line[-9:]

    rows = [replace_long_spaces(row) for row in rows]
    rows = [trim_edges(row) for row in rows]
    rows = remove_adjacent_duplicates(rows)
    rows = sort_desc(rows)
    rows = [keep_last_9_chars(row) for row in rows]
    return rows
